'use strict';

// The environment-agnostic runtime preamble shared by every generated harness.
// It implements the wasm-bindgen glue primitives that do not depend on the
// site being reversed: the object heap, the wasm<->JS string bridge, and the
// cached memory views.

const PREAMBLE = `// Generated by wasm2node. Environment-patching harness for a wasm-bindgen module.
// Do not edit by hand; regenerate with: wasm2node <file.wasm> --out <this-file>.js

const heap = [undefined, null, true, false];
function addHeapObject(obj) { heap.push(obj); return heap.length - 1; }
function getObject(idx) { return heap[idx]; }
function dropObject(idx) { /* keep indices stable; no reclaim */ }

let wasm;
let cachedUint8 = null;
let cachedView = null;
function getUint8Memory() {
  if (cachedUint8 === null || cachedUint8.buffer.detached === true ||
      (cachedUint8.buffer.detached === undefined && cachedUint8.buffer !== wasm.memory.buffer)) {
    cachedUint8 = new Uint8Array(wasm.memory.buffer);
  }
  return cachedUint8;
}
function getDataView() {
  if (cachedView === null || cachedView.buffer.detached === true ||
      (cachedView.buffer.detached === undefined && cachedView.buffer !== wasm.memory.buffer)) {
    cachedView = new DataView(wasm.memory.buffer);
  }
  return cachedView;
}

const cachedDecoder = new TextDecoder('utf-8', { ignoreBOM: true, fatal: true });
function getStringFromWasm(ptr, len) {
  ptr = ptr >>> 0;
  return cachedDecoder.decode(getUint8Memory().subarray(ptr, ptr + len));
}

const cachedEncoder = new TextEncoder();
function passStringToWasm(arg, malloc, realloc) {
  if (realloc === undefined) {
    const buf = cachedEncoder.encode(arg);
    const ptr = malloc(buf.length, 1) >>> 0;
    getUint8Memory().subarray(ptr, ptr + buf.length).set(buf);
    return { ptr, len: buf.length };
  }
  let len = arg.length;
  let ptr = malloc(len, 1) >>> 0;
  const mem = getUint8Memory();
  let offset = 0;
  for (; offset < len; offset++) {
    const code = arg.charCodeAt(offset);
    if (code > 0x7f) break;
    mem[ptr + offset] = code;
  }
  if (offset !== len) {
    if (offset !== 0) arg = arg.slice(offset);
    ptr = realloc(ptr, len, len = offset + arg.length * 3, 1) >>> 0;
    const view = getUint8Memory().subarray(ptr + offset, ptr + len);
    const ret = cachedEncoder.encodeInto(arg, view);
    offset += ret.written;
    // shrink the buffer to the bytes actually written, or free() will assert
    ptr = realloc(ptr, len, offset, 1) >>> 0;
  }
  return { ptr, len: offset };
}

function debugString(o) {
  const t = typeof o;
  if (t === 'number' || t === 'boolean' || o == null) return String(o);
  if (t === 'string') return '"' + o + '"';
  if (t === 'function') return 'Function(' + (o.name || '') + ')';
  if (Array.isArray(o)) return '[' + o.map(debugString).join(', ') + ']';
  try { return 'Object(' + JSON.stringify(o) + ')'; } catch { return 'Object'; }
}
`;

module.exports = { PREAMBLE };
